from html.parser import HTMLParser
from urllib.parse import urljoin
import sys
class P(HTMLParser):
    def __init__(self): super().__init__(); self.links=[]
    def handle_starttag(self,tag,attrs):
        if tag=='a':
            d=dict(attrs); h=d.get('href')
            if h: self.links.append((d.get('title',''),h))
p=P(); p.feed(open(sys.argv[1],encoding='utf-8',errors='ignore').read())
seen=set()
for title,h in p.links:
    u=urljoin('https://www.akgec.ac.in/',h)
    if 'akgec.ac.in' in u and u not in seen:
        seen.add(u); print(f'{title}\\t{u}')
PY"

